column4:
{"source_id": "unknown", "subject_summary": "Marco, a Brazilian student with extensive research experience, applied to US PhD programs (including Harvard) and ultimately chose to pursue a PhD in Molecular Genetics and Microbiology at Duke University after a Harvard rejection.", "nodes": [{"id": "n1", "type": "start_state", "label": "Food Engineering major in Brazil", "phase": 0, "evidence": "I majored in Food Engineering at the Federal University of Viçosa, Brazil", "certainty": "stated"}, {"id": "n2", "type": "milestone", "label": "Studied Biotechnology in France with courses and internship", "phase": 0, "evidence": "during this time, I also studied Biotechnology in France. I did one year of courses, and an internship, at the University of Lorraine", "certainty": "stated"}, {"id": "n3", "type": "milestone", "label": "Finished at top of class in France and approved for three funded master’s programs", "phase": 0, "evidence": "where I finished at the top of my class, and I was approved for three fully funded master’s programs.", "certainty": "stated"}, {"id": "n4", "type": "action", "label": "Chose master’s in Genetics and Molecular Biology in Brazil", "phase": 0, "evidence": "After that, I decided to pursue a masters in Genetics and Molecular Biology at the State University of Campinas, Brazil.", "certainty": "stated"}, {"id": "n5", "type": "milestone", "label": "Accumulated 5+ years research experience and five published articles", "phase": 0, "evidence": "despite studying at top universities and having +5 years of research experience, and five published articles at the time", "certainty": "stated"}, {"id": "n6", "type": "goal", "label": "Aim to get into a top US PhD program including Harvard", "phase": 0, "evidence": "despite studying at top universities and having +5 years of research experience, and five published articles at the time, I was still rejected from Harvard University.", "certainty": "implied"}, {"id": "n7", "type": "action", "label": "Applied for Fulbright scholarship (May 2021)", "phase": 1, "evidence": "In May 2021 I applied for the prestigious Fulbright scholarship", "certainty": "stated"}, {"id": "n8", "type": "milestone", "label": "Awarded Fulbright scholarship among about 15 Brazilians", "phase": 1, "evidence": "about 15 Brazilians, myself included, were awarded this scholarship for that year.", "certainty": "stated"}, {"id": "n9", "type": "milestone", "label": "Received list of eligible US universities and limit of five R1 applications", "phase": 1, "evidence": "After receiving the approval from Fulbright, we received a list of all the universities eligible to us. Though, we could only apply to five R1 universities in the US, which account for around 100 universities.", "certainty": "stated"}, {"id": "n10", "type": "action", "label": "Checked websites of ~100 universities for program and research fit", "phase": 1, "evidence": "So, I first accessed the websites of all 100 universities to check if their PhD programs and research areas would be a fit for me.", "certainty": "stated"}, {"id": "n11", "type": "action", "label": "Spoke with more than 20 PIs from 15 universities", "phase": 1, "evidence": "Then, before finally deciding which universities I would apply to, I spoke with more than 20 PIs from 15 universities on that list.", "certainty": "stated"}, {"id": "n12", "type": "action", "label": "Decided to apply to Duke, Cornell, UMD, OSU, and Harvard", "phase": 1, "evidence": "Ultimately, I decided to apply to Duke University, Cornell University, the University of Maryland (UMD), Ohio State University (OSU), and Harvard University.", "certainty": "stated"}, {"id": "n13", "type": "action", "label": "Prepared applications with statement, recommendation letters, and TOEFL", "phase": 1, "evidence": "The application for all the universities was pretty much the same: a statement of purpose... three letters of recommendation; and an elevated score on and internationally accepted English test.", "certainty": "implied"}, {"id": "n14", "type": "milestone", "label": "Had strong application materials (SOP, recommendations, TOEFL)", "phase": 1, "evidence": "My application was nearly perfect; my statement of purpose was highly insightful... I had recommendation letters from my previous advisors... In addition, my TOEFL score was several points above the minimum limit requested for the application.", "certainty": "stated"}, {"id": "n15", "type": "event", "label": "Did not receive Harvard interview invite by Dec 20 and emailed DGS", "phase": 2, "evidence": "By December 20th, all interview invites from Harvard were already sent, but I have not received anything, not even a rejection. So, I emailed the Director of Graduate Studies from the program, but I did not hear back from him.", "certainty": "stated"}, {"id": "n16", "type": "milestone", "label": "Invited to interview with Duke, then UMD, OSU, and Cornell", "phase": 2, "evidence": "Nonetheless, I was invited to interview with Duke, then UMD, OSU, and Cornell, in that order.", "certainty": "stated"}, {"id": "n17", "type": "milestone", "label": "First interview at Duke; impressed by students, area, faculty, and programs", "phase": 2, "evidence": "I actually had my first interview with Duke, and I was surprised that literally all of the current PhD students had so many nice things to say about the university, the Raleigh-Durham (NC) metropolitan area, and the faculty from the MGM department. In addition, I would have opportunities to earn additional certifications... to apply to the Duke Scholars in Molecular Medicine (DSMM) program.", "certainty": "stated"}, {"id": "n18", "type": "milestone", "label": "Recognized Duke as a definitive highlight despite upcoming interviews", "phase": 2, "evidence": "So, even though I would still interview with the other three universities, Duke was a definitive highlight.", "certainty": "stated"}, {"id": "n19", "type": "obstacle", "label": "Did not receive Harvard interview; felt devastated and sad", "phase": 3, "evidence": "Though, before finishing my PhD applications, Harvard was my obvious first choice... I confess that I was still hoping to receive a late interview invite. However, at this point, I realized I would not receive an invitation.

Well at first, I was devastated.", "certainty": "stated"}, {"id": "n20", "type": "milestone", "label": "Accepted to Duke and UMD on January 21", "phase": 3, "evidence": "I was accepted to four programs before getting this official rejection: (i) Molecular Genetics and Microbiology at Duke University on January 21st; (ii) Biological Sciences at the University of Maryland also on January 21st;", "certainty": "stated"}, {"id": "n21", "type": "milestone", "label": "Accepted to Cornell on February 24 and OSU on March 1", "phase": 3, "evidence": "(iii) Microbiology at Cornell University on February 24th; and (iv) Microbiology at the Ohio State University on March 1st.", "certainty": "stated"}, {"id": "n22", "type": "event", "label": "Received official Harvard rejection on March 7", "phase": 3, "evidence": "and the official rejection from Harvard came on March 7th.", "certainty": "stated"}, {"id": "n23", "type": "milestone", "label": "Reached emotional peace with Harvard’s decision by time of rejection", "phase": 3, "evidence": "But by the time I received it, I was finally at peace with their decision.", "certainty": "stated"}, {"id": "n24", "type": "outcome", "label": "Became first-year PhD student in Molecular Genetics and Microbiology at Duke", "phase": 4, "evidence": "I am 26 years old and a first-year PhD student in Molecular Genetics and Microbiology at Duke University.", "certainty": "stated"}, {"id": "n25", "type": "outcome", "label": "Reframed Harvard rejection as best thing that happened to him", "phase": 4, "evidence": "this rejection was probably the best thing that ever happened to me.

... so today I can easily say that being rejected from Harvard was the best thing that ever happened to me.", "certainty": "stated"}], "edges": [{"source": "n1", "target": "n2", "relation": "then"}, {"source": "n2", "target": "n3", "relation": "then"}, {"source": "n3", "target": "n4", "relation": "then"}, {"source": "n4", "target": "n5", "relation": "then"}, {"source": "n5", "target": "n6", "relation": "then"}, {"source": "n6", "target": "n7", "relation": "then"}, {"source": "n7", "target": "n8", "relation": "then"}, {"source": "n8", "target": "n9", "relation": "then"}, {"source": "n9", "target": "n10", "relation": "then"}, {"source": "n10", "target": "n11", "relation": "then"}, {"source": "n11", "target": "n12", "relation": "then"}, {"source": "n12", "target": "n13", "relation": "then"}, {"source": "n13", "target": "n14", "relation": "then"}, {"source": "n14", "target": "n15", "relation": "then"}, {"source": "n15", "target": "n16", "relation": "then"}, {"source": "n16", "target": "n17", "relation": "then"}, {"source": "n17", "target": "n18", "relation": "then"}, {"source": "n18", "target": "n19", "relation": "then"}, {"source": "n19", "target": "n20", "relation": "then"}, {"source": "n20", "target": "n21", "relation": "then"}, {"source": "n21", "target": "n22", "relation": "then"}, {"source": "n22", "target": "n23", "relation": "then"}, {"source": "n23", "target": "n24", "relation": "then"}, {"source": "n24", "target": "n25", "relation": "then"}], "unknowns": ["exact years of his Food Engineering degree and time spent at the University of Lorraine", "which three fully funded master’s programs he was approved for", "specific research projects underlying his 5+ years of experience and publications", "detailed timeline of his master’s in Genetics and Molecular Biology relative to the Fulbright application", "how he chose among Duke, UMD, Cornell, and OSU admission offers", "whether he ever received a reply from the Harvard Director of Graduate Studies"]}

column6:
{"source_id": "unknown", "goal": "Pursue an academic and career path aligned with personal happiness and passion rather than external expectations", "domain": "education / career choice / personal development", "nodes": [{"id": "r1", "primitive": "Op", "label": "Prioritize your happiness over social pressures and expectations from your circle", "evidence": "No matter the social pressures or the expectations that come from your circle, the key is to prioritize your happiness.", "certainty": "stated"}, {"id": "r2", "primitive": "NOT", "label": "Do not let yourself get drowned by negatives, what-ifs, and societal timelines", "evidence": "It’s easy to get drowned by the negatives, as I initially did, contemplating the what-ifs and societal timelines.", "certainty": "stated"}, {"id": "r3", "primitive": "Op", "label": "Anchor yourself to the knowledge that choosing happiness over societal expectations is the right path for you", "evidence": "Yet, in those moments, I anchor myself to the knowledge that choosing happiness over societal expectations was the right path for me.", "certainty": "stated"}, {"id": "r4", "primitive": "Op", "label": "Follow your passion and seek joy in your academic or career endeavours as a compass for decisions", "evidence": "The decision to follow my passion for Biology and Neuroscience, to seek joy in my academic endeavours, has been my compass.", "certainty": "implied"}, {"id": "r5", "primitive": "Op", "label": "Reshape your academic experience by embracing organization and ending procrastination", "evidence": "Determined to reshape my academic experience, I embraced a newfound sense of organization, I bid farewell to procrastination", "certainty": "implied"}, {"id": "r6", "primitive": "Op", "label": "Create a meticulously crafted daily task list that includes studies and personally meaningful extracurricular activities", "evidence": "created a meticulously crafted daily task list, that not only involved university work, but also extracurricular hobbies, hitting the gym and playing tennis.", "certainty": "implied"}, {"id": "r7", "primitive": "Op", "label": "Actively participate in lectures and immerse yourself in the subject area you care about", "evidence": "Active participation in lectures became my norm, and I immersed myself in all things Biology.", "certainty": "implied"}, {"id": "r8", "primitive": "Op", "label": "Seek science communication or similar engagement opportunities that fuel your passion", "evidence": "Fuelling my passion, I sought science communication opportunities, eagerly engaging in different activities.", "certainty": "implied"}, {"id": "r9", "primitive": "Op", "label": "Engage in discussions with experts (e.g., professors) in your field of interest", "evidence": "These ranged from lively discussions with professors", "certainty": "implied"}, {"id": "r10", "primitive": "Op", "label": "Seize chances to present your work at seminars or similar forums", "evidence": "seizing chances to present my work on Covid-19 at seminars.", "certainty": "implied"}, {"id": "r11", "primitive": "Op", "label": "Get involved in organizing committees for relevant consortiums and societies", "evidence": "Soon, I found myself deeply involved in organizing committees for science consortiums and societies.", "certainty": "implied"}, {"id": "r12", "primitive": "Op", "label": "Impart knowledge to younger students through teaching or demonstration sessions", "evidence": "A pivotal moment occurred when I began imparting knowledge to high school students through mini teaching sessions through information days.", "certainty": "implied"}, {"id": "r13", "primitive": "Op", "label": "Communicate complex concepts in accessible ways", "evidence": "I discovered the joy of communicating complex biological concepts in accessible ways.", "certainty": "implied"}, {"id": "r14", "primitive": "Op", "label": "Persist with genuine enthusiasm for your chosen field to improve academic performance", "evidence": "Through persistent efforts and genuine enthusiasm for Biology, I witnessed a remarkable turnaround in my academic performance at the university.", "certainty": "implied"}, {"id": "r15", "primitive": "Branch", "label": "Is your current academic or career path aligned with your passions or becoming more of a struggle than an exciting journey?", "evidence": "the path that I was on became more of a struggle than an exciting journey.", "certainty": "implied"}, {"id": "r16", "primitive": "Op", "label": "Calmly communicate with key stakeholders (e.g., family) when you realize your path is not right for you", "evidence": "Calmly, I made the call to my parents, confessing that the path that I was on became more of a struggle than an exciting journey.", "certainty": "implied"}, {"id": "r17", "primitive": "Op", "label": "Seek a program or path that is more aligned with your passions and offers a fresh start", "evidence": "However, a silver lining appeared in the form of a promising program at the University of Nicosia in Cyprus, in Human biology.

It was a fresh start, and a chance to pursue a path more aligned with my passions.", "certainty": "implied"}, {"id": "r18", "primitive": "Op", "label": "Leave the comfort zone of the familiar to discover strength and resilience", "evidence": "Leaving the comfort zone of the familiar, I discovered newfound strength and resilience.", "certainty": "implied"}, {"id": "r19", "primitive": "Op", "label": "Use friendships and supportive relationships as a source of encouragement and a nurturing environment", "evidence": "The friendships from the UK, through physically distant, became a source of support. Not Only those, but the new and old friendships in Cyprus precipitated further encouragement and provided a nurturing environment in which I could rebuild my academic journey.", "certainty": "implied"}, {"id": "r20", "primitive": "Op", "label": "Consider further specialization (e.g., a master’s degree) in an area that fascinates you and where you aspire to contribute", "evidence": "As my academic achievements flourished, I set my sights on a master’s degree in Molecular Medicine at the Cyprus Institute of Neurology and Genetics.

My aspirations were fuelled by the intriguing structure of the brain, the potential for groundbreaking discoveries and the prospect of contributing to the understanding of neurodegenerative diseases such as Alzheimer’s disease.", "certainty": "implied"}, {"id": "r21", "primitive": "Op", "label": "Apply for opportunities (e.g., PhD topics) that resonate with what you love and with teams you admire", "evidence": "an opportunity emerged – a PhD topic that resonated with what I loved. What made it even more enticing was the prospect of working with the same amazing team and supervisor that I had come to admire during my time as an MSc student. The decision to apply for this opportunity marked a turning point for my academic career.", "certainty": "implied"}, {"id": "r22", "primitive": "Op", "label": "Accept that detours and unconventional timelines can lead you closer to a fulfilling, purpose-driven pursuit", "evidence": "Each step, even the detours, has led me closer to a fulfilling and purpose-driven academic pursuit.", "certainty": "implied"}, {"id": "r23", "primitive": "Op", "label": "Do what makes you happy, even if your journey deviates from the conventional timeline", "evidence": "So, to those navigating similar crossroads, my advice is simple: do what makes you happy. Embrace the journey, even if it deviates from the conventional timeline.", "certainty": "stated"}], "edges": [{"source": "r1", "target": "r2", "condition": "always"}, {"source": "r2", "target": "r3", "condition": "not drowned by negatives and what-ifs"}, {"source": "r3", "target": "r4", "condition": "always"}, {"source": "r4", "target": "r15", "condition": "always"}, {"source": "r5", "target": "r6", "condition": "always"}, {"source": "r6", "target": "r7", "condition": "always"}, {"source": "r7", "target": "r8", "condition": "always"}, {"source": "r8", "target": "r9", "condition": "always"}, {"source": "r9", "target": "r10", "condition": "always"}, {"source": "r10", "target": "r11", "condition": "always"}, {"source": "r11", "target": "r12", "condition": "always"}, {"source": "r12", "target": "r13", "condition": "always"}, {"source": "r13", "target": "r14", "condition": "always"}, {"source": "r14", "target": "r20", "condition": "academic performance improving"}, {"source": "r15", "target": "r16", "condition": "path is more struggle than exciting journey"}, {"source": "r15", "target": "r14", "condition": "path is aligned with passions and exciting"}, {"source": "r16", "target": "r17", "condition": "always"}, {"source": "r17", "target": "r18", "condition": "always"}, {"source": "r18", "target": "r19", "condition": "always"}, {"source": "r19", "target": "r5", "condition": "always"}, {"source": "r20", "target": "r21", "condition": "fascination with specialized area present"}, {"source": "r21", "target": "r22", "condition": "always"}, {"source": "r22", "target": "r23", "condition": "always"}], "unknowns": ["Specific methods for resisting external voices beyond prioritizing happiness are not detailed", "Criteria for selecting a 'promising program' aligned with passions are not specified", "Concrete strategies for managing anxiety attacks during major applications are not described"]}

column4:
{"interview_id": "unknown", "subject_summary": "A founder with an already profitable YouTube network moved from Amsterdam to Thailand to remotely bootstrap a YouTube analytics startup over six months.", "nodes": [{"id": "n1", "type": "start_state", "label": "Already profitable YouTube network before moving", "phase": 0, "evidence": "my already profitable business — a YouTube network called the Panda Mix Show", "certainty": "stated"}, {"id": "n2", "type": "start_state", "label": "Living in Amsterdam before moving to Asia", "phase": 0, "evidence": "It’s been 6 months now since I moved from Amsterdam to Asia to work remotely.", "certainty": "stated"}, {"id": "n3", "type": "goal", "label": "Bootstrap a startup while working remotely from low-cost Thailand", "phase": 0, "evidence": "what I learnt from bootstrapping my startup from Thailand in six months", "certainty": "implied"}, {"id": "n4", "type": "action", "label": "Decided to move from Amsterdam to Asia to work remotely and chose Thailand for low cost and safety", "phase": 1, "evidence": "I moved from Amsterdam to Asia to work remotely. I chose Thailand for its low-cost of living and safety.", "certainty": "stated"}, {"id": "n5", "type": "obstacle", "label": "Thai visa will run out, limiting stay to about six months", "phase": 1, "evidence": "Since my visa will run out soon, I’ll have to leave the country", "certainty": "stated"}, {"id": "n6", "type": "action", "label": "Stayed in Thailand for six months under multiple-entry visa with extensions and visa runs", "phase": 1, "evidence": "With a multiple-entry visa, I was able to stay in the country for 60 days, I then had to go to the immigration office to extend it for 30 days, I then had to leave the country after that period and come back in to get another 60 days. And then extend it for another 30 days after that. And then leave the country again.

This gave me a total of 6 months to stay here.", "certainty": "stated"}, {"id": "n7", "type": "obstacle", "label": "Visa extension process costly and time-consuming", "phase": 1, "evidence": "But it meant paying $60 each extension, standing in queues all day, taking visa runs out of the country (even into Burma). It’s not ideal at all.", "certainty": "stated"}, {"id": "n8", "type": "action", "label": "Structured work routine into hyper-focused work sprints then two-week leisure breaks", "phase": 2, "evidence": "My work routine would be that I’d go on hyper-focused stints of working on something and then finishing it in a few weeks. And then I’d take a two week break and go to a paradise island or make a trip to Bangkok and have fun there", "certainty": "stated"}, {"id": "n9", "type": "action", "label": "Automated most tasks in existing YouTube business", "phase": 2, "evidence": "I grew my already profitable business — a YouTube network called the Panda Mix Show — by automating most of my tasks", "certainty": "stated"}, {"id": "n10", "type": "action", "label": "Hired two employees to handle remaining tasks in YouTube business", "phase": 2, "evidence": "and hiring two employees to do the rest.", "certainty": "stated"}, {"id": "n11", "type": "milestone", "label": "Existing YouTube network business grew further", "phase": 3, "evidence": "I grew my already profitable business — a YouTube network called the Panda Mix Show", "certainty": "stated"}, {"id": "n12", "type": "action", "label": "Built and launched a YouTube analytics startup from Thailand", "phase": 2, "evidence": "Besides that, I built and launched a YouTube analytics startup", "certainty": "stated"}, {"id": "n13", "type": "milestone", "label": "YouTube analytics startup gaining traction with first users signing up", "phase": 3, "evidence": "which is now gaining traction with its first users signing up.", "certainty": "stated"}, {"id": "n14", "type": "event", "label": "Joined remote-working entrepreneur community in Chiang Mai", "phase": 2, "evidence": "When I first arrived in the northern city of Chiang Mai — one of the hubs for remote working foreigners — I met a lot of great people that had profitable online businesses and had moved here from America, Europe and Australia. There was a nice clique of friends that would work and hang out together. It was like a little remote community.", "certainty": "stated"}, {"id": "n15", "type": "obstacle", "label": "Difficulty forming long-term friendships because everyone is passing through", "phase": 3, "evidence": "But then after a few months, slowly everyone started disappearing one-by-one. What I was experiencing was simply the passing-through of people... But that makes it hard to make long-term friends. It’s like being on the road….all…the..time.", "certainty": "stated"}, {"id": "n16", "type": "obstacle", "label": "Holiday environment and leisure options as distractions from work", "phase": 2, "evidence": "Even though there is a huge potential for focusing on your work here, you’re in a country where most people go for holidays. All those good things I just mentioned? Beaches, weather and cheap drinks? Yeah they are also distractions, if you don’t have the discipline to ignore them while you’re working.", "certainty": "stated"}, {"id": "n17", "type": "event", "label": "Frequently used co-working spaces available in Thailand", "phase": 2, "evidence": "There’s plenty of co-working spaces in Thailand. Bangkok has the huge Launchpad and the cosy Hubba heavily focusing on startups, while its second city of Chiang Mai has PunSpace, which caters more towards lifestyle entrepreneurs.", "certainty": "stated"}, {"id": "n18", "type": "event", "label": "Experienced strong focus from being abroad and having daily needs handled cheaply", "phase": 2, "evidence": "Moving to the other side of the world gives you an insane amount of focus which you can channel to really get anything done that you’re working on.

...I calculated all this saved me at least 6 hours daily.", "certainty": "stated"}, {"id": "n19", "type": "event", "label": "Encountered nascent, under-capitalized Thai startup scene", "phase": 2, "evidence": "For all its events, meet-ups and hackathons, the Thai startup scene is still very much in its infancy. There’s a lot of positive energy and enthusiasm going around, but Thai culture is still so intrinsically corporate focused.", "certainty": "stated"}, {"id": "n20", "type": "obstacle", "label": "Thai startup funding small and risk-averse", "phase": 2, "evidence": "The capital I have seen going round ranges from $50k to $500k... Everyone’s too risk-averse.", "certainty": "stated"}, {"id": "n21", "type": "event", "label": "Observed rapid inflation reducing Thailand’s cheapness", "phase": 3, "evidence": "When I came back after 6 months, the food had gone up 25%, the room 15% and the public transport 10%. Extrapolated that’s an annual inflation rate of over 35%... That means Thailand won’t be so cheap for very longer.", "certainty": "stated"}, {"id": "n22", "type": "event", "label": "Experienced pervasive sex tourism and prostitution in Thailand", "phase": 2, "evidence": "Thailand still has rampant amounts of sex tourism. That means seeing 65-year old foreigners walking with 18-year old girls on a daily basis. Prostitution is everywhere.", "certainty": "stated"}, {"id": "n23", "type": "event", "label": "Concluded six-month period in Thailand and need to leave as visa runs out", "phase": 4, "evidence": "Since my visa will run out soon, I’ll have to leave the country", "certainty": "stated"}, {"id": "n24", "type": "outcome", "label": "After six months, recommends Thailand as a good place to work remotely and bootstrap", "phase": 4, "evidence": "It was a great six months, and I would recommend Thailand to anyone wanting to take the dive to start working away from their own country. For all the bad, there’s more good. It’s comfortable, safe and Thais are one of the friendliest people I’ve ever met.", "certainty": "stated"}, {"id": "n25", "type": "outcome", "label": "Goal of bootstrapping from Thailand partially achieved: grown existing business and launched analytics startup with initial traction", "phase": 4, "evidence": "In these six months, I grew my already profitable business — a YouTube network called the Panda Mix Show — by automating most of my tasks and hiring two employees to do the rest. Besides that, I built and launched a YouTube analytics startup which is now gaining traction with its first users signing up.", "certainty": "implied"}], "edges": [{"source": "n1", "target": "n3", "relation": "then"}, {"source": "n2", "target": "n4", "relation": "then"}, {"source": "n3", "target": "n4", "relation": "then"}, {"source": "n4", "target": "n5", "relation": "then"}, {"source": "n5", "target": "n6", "relation": "then"}, {"source": "n6", "target": "n8", "relation": "then"}, {"source": "n8", "target": "n9", "relation": "then"}, {"source": "n9", "target": "n10", "relation": "then"}, {"source": "n10", "target": "n11", "relation": "then"}, {"source": "n8", "target": "n12", "relation": "then"}, {"source": "n12", "target": "n13", "relation": "then"}, {"source": "n4", "target": "n18", "relation": "then"}, {"source": "n18", "target": "n8", "relation": "then"}, {"source": "n4", "target": "n14", "relation": "then"}, {"source": "n14", "target": "n15", "relation": "then"}, {"source": "n4", "target": "n17", "relation": "then"}, {"source": "n4", "target": "n19", "relation": "then"}, {"source": "n19", "target": "n20", "relation": "then"}, {"source": "n6", "target": "n21", "relation": "then"}, {"source": "n4", "target": "n22", "relation": "then"}, {"source": "n6", "target": "n23", "relation": "then"}, {"source": "n23", "target": "n24", "relation": "then"}, {"source": "n11", "target": "n25", "relation": "then"}, {"source": "n13", "target": "n25", "relation": "then"}], "unknowns": ["Exact timeline of when automation and hiring for the YouTube network started relative to the move to Thailand.", "How much revenue or profit increased for the YouTube network as a result of automation and hiring.", "Whether the YouTube analytics startup reached profitability or further growth milestones beyond initial traction.", "Specific number of users or type of customers for the YouTube analytics startup.", "Detailed tech stack, team composition, or funding situation of the YouTube analytics startup.", "Whether the founder plans to continue working on the startup from another country after leaving Thailand."]}

column6:
{"source_id": "unknown", "goal": "Bootstrap and grow a profitable SaaS company as a (solo) founder", "domain": "entrepreneurship / SaaS / bootstrapping", "nodes": [{"id": "r1", "primitive": "Op", "label": "Make product/market fit the core focus and build something people truly need", "evidence": "In retrospect on my projects that didn’t work, product/market fit was something that I thought would come later and that I just wasn’t finding the right people but the reality was I wasn’t building something that people needed.", "certainty": "implied"}, {"id": "r2", "primitive": "Op", "label": "Solve a specific urgent problem for customers", "evidence": "Talking to customers while you’re building something that fixes an urgent problem for them is so much fun.", "certainty": "implied"}, {"id": "r3", "primitive": "Op", "label": "Launch an open-source version of your product to attract users and validate demand", "evidence": "I just released it as an open-source project on Github with a little webpage explaining how to use it.", "certainty": "stated"}, {"id": "r4", "primitive": "Op", "label": "Host the open-source software as a paid SaaS service and charge based on usage", "evidence": "I started out hosting our open source software and charged customers for how much they used the hosted service, which enabled Prerender.io to be profitable from day one.", "certainty": "stated"}, {"id": "r5", "primitive": "Op", "label": "Use the open-source server as a marketing tool for the SaaS service", "evidence": "If you can open source your product but have a SaaS service to charge people that don't want to host it themselves, the open-source server almost becomes a marketing tool for your SaaS service.", "certainty": "stated"}, {"id": "r6", "primitive": "Op", "label": "Allow prospects and large customers to test and self-host via open source to build trust", "evidence": "Our open-source code also allowed prospective customers to give it a test run before signing up. It also gave our larger customers peace of mind since they could run our open source server if they thought our hosted service might somehow disappear one day.", "certainty": "stated"}, {"id": "r7", "primitive": "Op", "label": "Spend significant time talking to customers and fixing issues they encounter", "evidence": "I mainly spent my days talking to customers/fixing things that were causing issues", "certainty": "stated"}, {"id": "r8", "primitive": "Op", "label": "Continuously scale infrastructure to handle new customers", "evidence": "and then spent my nights scaling to handle new customers.", "certainty": "stated"}, {"id": "r9", "primitive": "Op", "label": "Use customer conversations to prioritize the most important work at each moment", "evidence": "it felt more like I was constantly putting out fires (while juggling too) at the time, but when I look back that was the best way to force me to work on the most important thing at each moment in time.", "certainty": "implied"}, {"id": "r10", "primitive": "Op", "label": "Personally answer support questions as much as possible", "evidence": "I’ve learned that as a founder you should personally answer support questions as much as you can.", "certainty": "stated"}, {"id": "r11", "primitive": "Op", "label": "Evolve the product by listening to customers and slowly changing things over time", "evidence": "So much of Prerender.io evolved from listening to customers and just slowly changing things over time.", "certainty": "stated"}, {"id": "r12", "primitive": "NOT", "label": "Avoid uncontrolled feature creep", "evidence": "You have to be careful about feature creep", "certainty": "stated"}, {"id": "r13", "primitive": "Op", "label": "Fix issues or add new features that provide broad value to all SaaS customers", "evidence": "but the great thing about SaaS products is fixing an issue or adding a new feature means everyone else is going to benefit from those changes as well.", "certainty": "implied"}, {"id": "r14", "primitive": "Op", "label": "Remove features that don’t provide much value or that make things complicated", "evidence": "Similarly, don’t be afraid to remove features that don’t provide much value or make things complicated.", "certainty": "stated"}, {"id": "r15", "primitive": "Op", "label": "Relentlessly automate any manual processes to enable solo scaling", "evidence": "I was able to grow Prerender.io being the sole employee for such a long time because I would relentlessly automate any manual processes.", "certainty": "stated"}, {"id": "r16", "primitive": "Op", "label": "Use repeated support questions as a signal to optimize and automate your time", "evidence": "Answering support emails helps with this too because you’re going to get the same questions over and over. It forces you to optimize your time.", "certainty": "stated"}, {"id": "r17", "primitive": "Op", "label": "Leverage developer blog posts and documentation references to drive organic traffic and SEO", "evidence": "With Prerender.io being a developer tool, many blog posts were written about Prerender.io because they could show our open source code and then just include a link to our hosted service at the end.

Those early blog posts helped give us a huge boost in our own SEO.", "certainty": "stated"}, {"id": "r18", "primitive": "NOT", "label": "Do not rely on paid ads, webinars, or partnerships when organic demand is strong", "evidence": "We didn't do ads, no webinars, and no partnerships.", "certainty": "stated"}, {"id": "r19", "primitive": "Op", "label": "Solve a specific need in a growing technology area to benefit from organic growth", "evidence": "I just got really lucky in that we solved a specific need that companies were willing to pay for and javascript frameworks were growing at such a fast pace for all different kinds of websites.", "certainty": "implied"}, {"id": "r20", "primitive": "Op", "label": "Use tools that make support email handling clean and personal", "evidence": "HelpScout is a super awesome tool for handling support emails. All the other tools I tried gave you really gross HTML in an email and I love that HelpScout just feels like a personalized, normal email.", "certainty": "stated"}, {"id": "r21", "primitive": "Op", "label": "Use cloud infrastructure (e.g., AWS) to move fast and handle scaling with ease", "evidence": "We use Amazon Web Services which helps us move fast and handle scaling with ease. I’m sure everyone knows about AWS these days, but just being able to focus on the code and not the infrastructure is a huge boost in productivity.", "certainty": "stated"}, {"id": "r22", "primitive": "Op", "label": "Adopt a subscription billing system instead of maintaining a custom invoicing solution as you grow", "evidence": "I started out creating my own internal invoicing system which was great in the beginning but it ended up taking up too much of my time to manage as we grew. We recently started using Chargebee for subscription billing and it’s been really nice to automate our billing a little more.", "certainty": "stated"}, {"id": "r23", "primitive": "Op", "label": "Use internal tools (dashboards, error tracking, communication) that help your team move faster", "evidence": "Other notable tools are mostly internal things like Redash (internal graphs/dashboards), Sentry (internal code error tracking), Slack (mainly gif sharing? Some chatting too).

Anything that helps us move faster is a great thing!", "certainty": "stated"}, {"id": "r24", "primitive": "Op", "label": "Be willing to make mistakes and learn from products that fizzle out", "evidence": "For entrepreneurs who are just starting or entrepreneurs who are veterans, this is really cliché but don’t be afraid to make mistakes. I’ve built plenty of things/products that have fizzled out but I always learned something along the way.", "certainty": "stated"}, {"id": "r25", "primitive": "Op", "label": "Stay humble and use upsetting customer experiences as lessons to avoid repeating mistakes", "evidence": "I’ve felt really stupid and had customers get upset but that’s always in the back of my mind so I don’t repeat the same mistake. You’ll never stop making mistakes so stay humble enough to learn from them!", "certainty": "stated"}, {"id": "r26", "primitive": "Op", "label": "Grow the company carefully instead of hiring aggressively", "evidence": "We are looking to grow carefully, and so far that has worked really well for us!", "certainty": "stated"}], "edges": [{"source": "r1", "target": "r2", "condition": "always"}, {"source": "r2", "target": "r3", "condition": "always"}, {"source": "r3", "target": "r4", "condition": "always"}, {"source": "r4", "target": "r5", "condition": "always"}, {"source": "r5", "target": "r6", "condition": "always"}, {"source": "r6", "target": "r7", "condition": "always"}, {"source": "r7", "target": "r8", "condition": "always"}, {"source": "r7", "target": "r9", "condition": "always"}, {"source": "r7", "target": "r10", "condition": "always"}, {"source": "r10", "target": "r11", "condition": "always"}, {"source": "r11", "target": "r12", "condition": "always"}, {"source": "r12", "target": "r13", "condition": "feature changes considered"}, {"source": "r13", "target": "r14", "condition": "features provide little value or add complexity"}, {"source": "r10", "target": "r15", "condition": "support questions reveal manual processes"}, {"source": "r15", "target": "r16", "condition": "repeated questions observed"}, {"source": "r3", "target": "r17", "condition": "open-source product adopted by developers"}, {"source": "r17", "target": "r18", "condition": "organic traffic sufficient"}, {"source": "r18", "target": "r19", "condition": "organic-first growth strategy chosen"}, {"source": "r7", "target": "r20", "condition": "support email volume requires tooling"}, {"source": "r8", "target": "r21", "condition": "need to handle scaling with ease"}, {"source": "r4", "target": "r22", "condition": "billing complexity increases with growth"}, {"source": "r22", "target": "r23", "condition": "internal operations expanded"}, {"source": "r24", "target": "r25", "condition": "mistakes and upset customers experienced"}, {"source": "r25", "target": "r26", "condition": "growth decisions considered"}], "unknowns": ["How to initially identify a promising urgent problem beyond the examples given", "Specific criteria or metrics used to judge product/market fit before and after launch", "How to price usage for the hosted service in different markets", "Concrete methods to prevent feature creep while still innovating", "Detailed automation techniques or frameworks used for different manual processes", "How to decide the threshold at which to switch from custom invoicing to subscription billing tools", "Exact hiring criteria or triggers for moving from solo founder to adding staff"]}
